// Example: typed tool call stream consumer
package examples

import (
  "context"
  "fmt"
  "time"

  rwsdk "github.com/redwood-inference/go-sdk"
)

// ToolCall represents a structured tool payload returned by the model.
type ToolCall struct {
  Name string `json:"name"`
  Args map[string]string `json:"args"`
}

func consumeToolStream(ctx context.Context, stream rwsdk.Stream) error {
  // Create a typed decoder for ToolCall events
  dec := rwsdk.NewDecoder[ToolCall](stream.Reader())
  sink := rwsdk.NewStreamSink[ToolCall](ctx, func(ev ToolCall) error {
    fmt.Printf("received tool: %s args=%v\n", ev.Name, ev.Args)
    return nil
  })

  // Start consuming, handling pause/resume implied by backpressure from the callback
  err := dec.StreamInto(ctx, sink)
  if err != nil {
    return fmt.Errorf("stream decode failed: %w", err)
  }
  // Graceful close: ensure sink flushed
  sink.CloseWithError(nil)
  // Wait a short time for background flush if any
  time.Sleep(10 * time.Millisecond)
  return nil
}
